import csv,json,pathlib,os
folder=pathlib.Path('D1b/c1')
rows=list(csv.DictReader(open('D1b/in/part-talos.tsv'),delimiter='\t'))
output=folder/'part-talos.tsv'
header=['id','decision','sentences','what_it_does','basis','reason']
existing=list(csv.DictReader(open(output),delimiter='\t')) if output.exists() else []
seen={r['id'] for r in existing}
def append(i,decision,sentences,what,basis,reason):
 r=rows[i]
 if r['id'] in seen:return
 assert len(what.split())<=15 and len(reason.split())<=30,(i,what,reason)
 assert all('\t' not in x and '\n' not in x for x in [what,basis,reason])
 new=not output.exists()
 with output.open('a',newline='') as f:
  w=csv.writer(f,delimiter='\t',lineterminator='\n')
  if new:w.writerow(header)
  w.writerow([r['id'],decision,sentences,what,basis,reason]);f.flush();os.fsync(f.fileno())
 seen.add(r['id'])
